-- Retain legacy IDs and base portions for editing past intake entries.
alter table public.food_catalog
  add column is_listed boolean not null default true,
  add column source_url text check (source_url is null or source_url like 'https://%'),
  add column brand text,
  add column package_size text,
  alter column protein_g type numeric(6, 2),
  drop constraint food_catalog_serving_check;

update public.food_catalog
set is_listed = false
where id in ('chicken', 'shake', 'yogurt', 'chicken-salad', 'tofu-bowl');

update public.food_catalog
set
  protein_g = 6.5,
  serving_amount = 1,
  description = '중간 크기 1개 (껍데기 제외 약 48g)',
  source_url = 'https://various.foodsafetykorea.go.kr/nutrient/general/food/detail.do?dbGrpCm=A&searchFoodCd=R110-003000046-0000'
where id = 'eggs';

update public.food_catalog as catalog
set protein_g = defaults.protein_g
from (values ('meal-carb', 14), ('meal-balanced', 29), ('meal-meat-fish', 49), ('meal-protein', 75)) as defaults(id, protein_g)
where catalog.id = defaults.id;

alter table public.food_catalog
  add constraint food_catalog_serving_check check (
    (estimate_preset and kind = 'meal' and serving_amount is null and serving_unit is null)
    or (
      not estimate_preset and serving_amount is not null and serving_amount > 0 and serving_unit is not null
      and serving_unit in ('g', '개', '회분', '컵', '그릇', '팩', '병')
      and (not is_listed or (serving_amount = 1 and serving_unit <> 'g'))
    )
  );

